            var max_id: u32 = 0;
            _ = &max_id;
            switch (server.userRoutes()) {
inline else => |user_routes| {
for (cp_mut_slice(&user_routes)) |*user_route| {
                _ = &user_route;
                const decl: *const jsc.API.ServerConfig.RouteDeclaration = (&(user_route.*).route);
                max_id = @max(max_id, (user_route.*).id);
                _ = try routes.append(.{ .route_id = @intCast((user_route.*).id), .path = bun.String.init(decl.path), .@"type" = .api, .param_names = null, .param_names_len = 0, .script_line = -1, .file_path = .empty });
            }
},
}
            for (config.static_routes.items) |*route| {
                _ = &route;
                _ = try routes.append(.{ .route_id = @intCast((max_id + 1)), .path = bun.String.init((route.*).path), .@"type" = (switch ((route.*).route) {
.html => .html,
.@"static" => .@"static",
else => .default,
}), .script_line = -1, .param_names = null, .param_names_len = 0, .file_path = (switch ((route.*).route) {
.html => |html| bun.String.init(html.data.bundle.data.path),
else => .empty,
}) });
